const payload = $input.first().json.body ?? $input.first().json;
const recipients = payload.recipients?.whatsapp ?? [];
const santri = payload.santri ?? {};
const group = payload.group ?? {};
const ringkasan = payload.ringkasan?.baris ?? {};

function normalizePhone(phone) {
  const raw = String(phone ?? '').replace(/[^0-9]/g, '');
  if (raw.startsWith('08')) return '62' + raw.slice(1);
  if (raw.startsWith('8')) return '62' + raw;
  return raw;
}

const summaryText = Object.entries(ringkasan)
  .map(([label, value]) => `- ${label}: ${value ?? '-'}`)
  .join('\n');

return recipients.map((recipient) => {
  const roleLabel = recipient.role === 'ibu' ? 'Ibu' : 'Bapak';
  const kelasLabel = group.kelas === 'ikhwan'
    ? 'ikhwan (putra)'
    : 'akhwat (putri)';
  const message = `Assalamu'alaikum ${roleLabel} ${recipient.name ?? ''},\n\nAlhamdulillah, data pendaftaran SPSB untuk ananda *${santri.nama_lengkap ?? '-'}* sudah masuk dan diterima oleh sistem.\n\n*Ringkasan data:*\n${summaryText}\n\n*Informasi group kelas ${kelasLabel}:*\n${group.aturan ?? '-'}\n${group.link ? `Link group: ${group.link}` : 'Link group belum tersedia. Admin akan mengirimkan link menyusul.'}\n\nTautan cetak pendaftaran:\n${payload.links?.cetak ?? '-'}\n\nJazakumullah khairan.\nPanitia SPSB`;

  return {
    json: {
      phone: normalizePhone(recipient.phone),
      role: recipient.role,
      name: recipient.name,
      message,
      payload
    }
  };
});
